package main

import "fmt"

func main() {
    // Method 1: Using a pointer to a string (common pattern)
    // The default value is nil, which represents an empty string in this context
    greet := func(name *string) {
        if name == nil {
            fmt.Println("Hello, Guest!")
        } else {
            fmt.Printf("Hello, %s!\n", *name)
        }
    }

    var defaultName *string = nil
    greet(defaultName) // Output: Hello, Guest!

    user := "Alice"
    greet(&user)       // Output: Hello, Alice!

    // Method 2: Using a function with a variadic argument or optional parameter logic
    // Golang doesn't support true optional parameters, so we often use a wrapper or check for nil
    greetWithDefault := func(name string) {
        if name == "" {
            fmt.Println("Hello, World!")
        } else {
            fmt.Printf("Hello, %s!\n", name)
        }
    }

    greetWithDefault("") // Output: Hello, World!
    greetWithDefault("Bob") // Output: Hello, Bob!
}
